insert into public.warning_lights (slug, name, colors, severity, symbol_hint, meaning, action, drive_advice, brand_notes, brand_severity, sort_order, repair_service, repair_alt_services, repair_cost_low, repair_cost_high, needs_diagnosis, repair_note) values
('check-engine', 'Check engine light', array['amber']::text[], 'soon', 'Outline of an engine block seen from the side, sometimes with the word CHECK.', 'The engine computer found a problem with the engine, fuel or emissions system. Causes range from a loose gas cap to a misfire.', 'If it''s steady, tighten the gas cap and get the code read soon (many auto parts stores do it free). If it''s flashing, the engine is misfiring: slow down and get to a mechanic right away.', 'Steady: OK to drive short-term. Flashing: avoid driving.', '{"tesla": "Teslas have no gasoline engine, so this symbol won''t appear; check the touchscreen alerts instead."}'::jsonb, '{}'::jsonb, 1, 'Engine', array['Electrical']::text[], 100, 1000, true, 'Often a loose gas cap (free), an oxygen sensor ($200–$500) or ignition coils and spark plugs ($150–$400). A catalytic converter can cost $1,000 or more. If the light is flashing, stop driving.'),
('oil-pressure', 'Oil pressure warning', array['red']::text[], 'stop', 'Old-fashioned oil can with a drip coming from the spout.', 'The engine isn''t getting enough oil pressure. Driving like this can destroy the engine within minutes.', 'Pull over safely and turn the engine off. Once it has rested, check the oil level and add oil if it''s low. If the level is fine or the light stays on, have the car towed.', 'Do not drive.', '{}'::jsonb, '{}'::jsonb, 2, 'Engine', array['Oil change']::text[], 80, 800, true, 'Often the oil is just very low: a top-off or oil change ($50–$120). A bad pressure sensor runs $100–$300; an oil pump repair can be $800 or more. Don''t drive with this light on.'),
('oil-level-low', 'Low engine oil level', array['amber']::text[], 'soon', 'Oil can with a wavy line underneath, or oil can with MIN.', 'The oil level sensor reads low oil. This is a level warning, not a pressure warning.', 'Check the dipstick and top up with the oil type in your owner''s manual. Look for leaks if it keeps dropping.', 'OK to drive to a store or service station.', '{"bmw": "BMWs often have no dipstick; check the level in iDrive under Vehicle Status.", "mercedes-benz": "Check the level in the instrument cluster menu."}'::jsonb, '{}'::jsonb, 3, 'Oil change', array['Engine']::text[], 40, 120, false, 'Usually a top-off or an oil change. If it keeps coming back, ask the shop to check for a leak or oil burning.'),
('coolant-temp', 'Engine temperature warning', array['red']::text[], 'stop', 'Thermometer standing in wavy lines of liquid.', 'The engine is overheating.', 'Pull over and turn the engine off. Never open the radiator cap while hot. Once cool, check the coolant level and have the cooling system inspected.', 'Do not drive until it has cooled and been checked.', '{}'::jsonb, '{}'::jsonb, 4, 'Engine', array[]::text[], 150, 1000, true, 'Common causes: low coolant or a leak ($100–$400), a thermostat ($200–$450) or a water pump ($400–$900). Driving while overheating can ruin the engine.'),
('coolant-cold', 'Engine cold indicator', array['blue']::text[], 'info', 'Blue thermometer in wavy lines of liquid.', 'The engine hasn''t reached normal operating temperature yet.', 'Nothing to fix. Drive gently until it goes out.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 5, null, array[]::text[], null, null, false, null),
('battery-charging', 'Battery / charging warning', array['red']::text[], 'soon', 'Rectangle shaped like a car battery with + and - marks.', 'The charging system isn''t working, so the car is running on battery power alone.', 'Turn off non-essential electronics such as the radio and seat heaters, and drive straight to a mechanic. The car may stall once the battery drains.', 'Drive only a short distance, directly to help.', '{}'::jsonb, '{}'::jsonb, 6, 'Electrical', array['Engine']::text[], 120, 900, true, 'Usually the battery ($150–$300) or the alternator ($400–$900). Many shops test the charging system for free.'),
('brake-system', 'Brake system warning', array['red']::text[], 'stop', 'Circle with an exclamation mark inside, between two curved brackets, or the word BRAKE.', 'Either the parking brake is on, or the brake system has a problem such as low brake fluid.', 'Make sure the parking brake is fully released. If it stays on, check the brake fluid level. If the pedal feels soft or different, stop and have the car towed.', 'Do not drive if braking feels different.', '{}'::jsonb, '{}'::jsonb, 7, 'Brakes', array[]::text[], 100, 600, false, 'First make sure the parking brake is fully off. Otherwise it''s often low brake fluid from worn pads ($150–$350 per axle); a leak or master cylinder runs $300–$600.'),
('parking-brake', 'Parking brake on', array['red','amber']::text[], 'info', 'Circle with the letter P inside, between two curved brackets.', 'The parking brake (electronic or manual) is applied.', 'Release the parking brake before driving. If it won''t release or the light is amber and flashing, the electronic parking brake has a fault.', 'Release before driving.', '{}'::jsonb, '{}'::jsonb, 8, null, array[]::text[], null, null, false, null),
('abs', 'ABS warning', array['amber']::text[], 'soon', 'The letters ABS inside a circle between two curved brackets.', 'The anti-lock braking system is off. Normal brakes still work, but the wheels can lock in a hard stop.', 'Drive carefully with extra following distance, especially in rain or snow, and have it checked soon.', 'OK to drive carefully.', '{}'::jsonb, '{}'::jsonb, 9, 'Brakes', array['Electrical']::text[], 150, 1200, true, 'Usually a wheel-speed sensor ($150–$400). A failed ABS module can cost $800–$1,500. Normal braking still works, but without anti-lock.'),
('brake-pad-wear', 'Brake pad wear', array['amber']::text[], 'soon', 'Circle between curved brackets with dashed lines on each side.', 'The brake pads are worn down to their wear sensors.', 'Book a brake service soon. Waiting too long can damage the rotors.', 'OK to drive; schedule service.', '{}'::jsonb, '{}'::jsonb, 10, 'Brakes', array[]::text[], 150, 500, false, 'New pads run about $150–$300 per axle, or $300–$500 with rotors.'),
('tpms', 'Low tire pressure (TPMS)', array['amber']::text[], 'soon', 'Horseshoe-shaped tire cross-section with an exclamation mark inside.', 'One or more tires is significantly underinflated.', 'Check all four tires with a gauge and fill to the pressure on the driver''s door sticker. If it flashes for a minute then stays on, a sensor needs service.', 'Drive slowly to the nearest air pump.', '{}'::jsonb, '{}'::jsonb, 11, 'Tires', array[]::text[], 20, 200, false, 'Often just low air (free to $20 at a shop). A failed pressure sensor is about $50–$200 per wheel.'),
('traction-control', 'Traction / stability control', array['amber']::text[], 'info', 'Car with two wavy skid lines behind it.', 'Flashing means the system is actively helping you keep grip. Steady means it''s off or has a fault.', 'If flashing, ease off the accelerator. The road is slippery. If steady, check whether it was switched off by a button, and have it inspected if it stays on.', 'OK to drive carefully.', '{"chevrolet": "Chevrolet calls this StabiliTrak; a ''Service StabiliTrak'' message means a fault.", "gmc": "GMC calls this StabiliTrak.", "nissan": "Nissan also shows a SLIP indicator when the system is working."}'::jsonb, '{}'::jsonb, 12, null, array[]::text[], null, null, false, null),
('traction-off', 'Traction / stability control off', array['amber']::text[], 'info', 'Car with skid lines and the word OFF.', 'Traction or stability control has been turned off.', 'Press the traction-control button to turn it back on unless you''re stuck in snow or mud.', 'OK to drive; turn back on for normal driving.', '{}'::jsonb, '{}'::jsonb, 13, null, array[]::text[], null, null, false, null),
('airbag', 'Airbag warning', array['red','amber']::text[], 'soon', 'Seated person with a seatbelt and a large circle (airbag) in front.', 'The airbag system has a fault, so airbags may not deploy in a crash.', 'Make sure nothing is blocking or unplugged under the front seats, then have the system checked soon. This is a safety issue.', 'OK to drive, but get it fixed soon.', '{}'::jsonb, '{}'::jsonb, 14, 'Electrical', array[]::text[], 100, 1000, true, 'Often a seat or seatbelt connector or the clock spring in the steering wheel ($150–$600). The airbags may not deploy until it''s fixed.'),
('seatbelt', 'Seatbelt reminder', array['red']::text[], 'info', 'Seated person wearing a diagonal seatbelt.', 'Someone in a front seat isn''t buckled.', 'Buckle up. A heavy bag on the passenger seat can also trigger it.', 'Buckle up first.', '{}'::jsonb, '{}'::jsonb, 15, null, array[]::text[], null, null, false, null),
('power-steering', 'Power steering warning', array['red','amber']::text[], 'soon', 'Steering wheel with an exclamation mark beside it.', 'The power steering system has a fault, so steering may become very heavy.', 'Drive slowly to a safe place. Restarting the car sometimes clears it; if not, have it checked.', 'Drive with caution only if steering still feels normal.', '{}'::jsonb, '{}'::jsonb, 16, 'Engine', array['Alignment','Electrical']::text[], 150, 1200, true, 'Hydraulic systems: often low fluid or a leak ($100–$500). Electric power steering faults may need a motor or rack ($800–$1,500).'),
('transmission-temp', 'Transmission temperature', array['red','amber']::text[], 'stop', 'Gear cog with a thermometer inside.', 'The transmission fluid is overheating, often from towing or stop-and-go traffic in heat.', 'Pull over, put it in Park, and let the engine idle a few minutes to cool. Have the transmission fluid checked.', 'Stop and let it cool before continuing.', '{}'::jsonb, '{}'::jsonb, 17, 'Transmission', array[]::text[], 150, 1500, true, 'Pull over and let it cool. A fluid service is $150–$300; a cooler, line or solenoid repair costs more.'),
('master-warning', 'Master warning', array['red','amber']::text[], 'soon', 'Triangle with an exclamation mark inside.', 'A general alert that comes on together with a message on the instrument display.', 'Read the message on the dashboard display. That message tells you the actual problem.', 'Depends on the message shown.', '{"toyota": "Toyota and Lexus use this as the Master Warning; it always pairs with a message in the multi-information display.", "lexus": "Pairs with a message in the multi-information display.", "honda": "Check the driver information interface for the specific message."}'::jsonb, '{}'::jsonb, 18, 'Inspection', array['Engine','Electrical']::text[], 80, 200, true, 'This light points to a message on your dashboard display, so read that first. A shop can scan the car to find the cause.'),
('service-wrench', 'Service / maintenance indicator', array['amber']::text[], 'info', 'A wrench (spanner), sometimes with letters or a number next to it.', 'A scheduled service is due.', 'Book routine maintenance. Most cars let you reset this after service.', 'OK to drive.', '{"honda": "This is Honda''s Maintenance Minder. The code next to the wrench (like A1 or B12) says which services are due: A = oil change, B = oil + inspection, 1 = tire rotation.", "acura": "This is Acura''s Maintenance Minder; the code shows which services are due.", "ford": "On Fords an amber wrench means a powertrain fault, not routine service. Have it checked soon; the car may limit power.", "lincoln": "An amber wrench indicates a powertrain fault; have it checked soon."}'::jsonb, '{"ford": "soon", "lincoln": "soon"}'::jsonb, 19, 'Inspection', array['Oil change','Engine','Transmission']::text[], 80, 400, true, 'On most cars it means scheduled maintenance is due (an oil change and inspection, about $80–$200). On Fords and Lincolns it means a powertrain fault that needs a scan.'),
('low-fuel', 'Low fuel', array['amber']::text[], 'info', 'Gas pump.', 'The fuel tank is nearly empty, usually about 30 to 50 miles left.', 'Fill up soon. Running out can damage the fuel pump.', 'Head to a gas station.', '{}'::jsonb, '{}'::jsonb, 20, null, array[]::text[], null, null, false, null),
('washer-fluid', 'Low washer fluid', array['amber']::text[], 'info', 'Windshield with a fountain of spray.', 'The windshield washer fluid reservoir is low.', 'Top up with washer fluid. Use a de-icer formula in winter.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 21, null, array[]::text[], null, null, false, null),
('door-ajar', 'Door open', array['red']::text[], 'info', 'Car seen from above with a door swung open.', 'A door, the hood or the trunk isn''t fully closed.', 'Close every door, the hood and the trunk firmly.', 'Close it before driving.', '{}'::jsonb, '{}'::jsonb, 22, null, array[]::text[], null, null, false, null),
('bulb-out', 'Exterior bulb failure', array['amber']::text[], 'info', 'Light bulb with an exclamation mark or rays.', 'A headlight, brake light or turn signal bulb has burned out.', 'Walk around the car with the lights on to find it, then replace the bulb.', 'OK to drive; fix soon (it''s a ticketable offense).', '{}'::jsonb, '{}'::jsonb, 23, null, array[]::text[], null, null, false, null),
('glow-plug', 'Glow plug (diesel)', array['amber']::text[], 'info', 'Coil or spiral shape.', 'On diesel engines, the glow plugs are warming the cylinders before starting.', 'Wait for it to go out before starting the engine. If it flashes while driving, there''s an engine fault.', 'Wait for it to go out.', '{}'::jsonb, '{}'::jsonb, 24, null, array[]::text[], null, null, false, null),
('dpf', 'Diesel particulate filter', array['amber']::text[], 'soon', 'Box with dots inside, like a filter, sometimes with lines on each side.', 'The diesel particulate filter is clogging up.', 'Drive at highway speed for 15 to 20 minutes so it can clean itself. If the light stays on, see a mechanic.', 'OK to drive; a highway drive often clears it.', '{}'::jsonb, '{}'::jsonb, 25, 'Engine', array[]::text[], 150, 3000, true, 'Often cleared by a long highway drive or a forced regeneration at a shop ($150–$400). Cleaning or replacing the filter costs $1,000–$3,000 or more.'),
('def-low', 'Low diesel exhaust fluid (DEF / AdBlue)', array['amber']::text[], 'soon', 'Droplet or fluid container, often with DEF or AdBlue text.', 'The diesel exhaust fluid tank is low. When it runs out, many trucks limit speed or won''t restart.', 'Refill DEF at a gas station or auto parts store.', 'Refill soon.', '{}'::jsonb, '{}'::jsonb, 26, 'Engine', array[]::text[], 30, 800, false, 'Usually just a refill of diesel exhaust fluid (about $50 at a shop). A failed DEF heater or pump runs $500–$1,500.'),
('epc', 'EPC (Electronic Power Control)', array['amber']::text[], 'soon', 'The letters EPC.', 'A fault in the throttle or engine management system. The car may go into reduced-power ''limp'' mode.', 'Have the fault codes read soon.', 'Drive gently to a mechanic.', '{"volkswagen": "EPC is a Volkswagen/Audi light, often caused by a throttle body or brake light switch fault.", "audi": "EPC often points to the throttle body or brake light switch."}'::jsonb, '{}'::jsonb, 27, 'Electrical', array['Engine']::text[], 150, 1000, true, 'Common causes: the throttle body ($300–$700), a brake light switch ($100–$200) or a sensor.'),
('lane-assist', 'Lane keeping assist', array['green','amber']::text[], 'info', 'Car between two lane lines, sometimes with a steering wheel.', 'Green means lane keeping is active. Amber means it''s unavailable or has a fault, often because the camera is blocked by dirt, snow or glare.', 'If amber, clean the windshield in front of the camera. If it stays amber, have it checked.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 28, null, array[]::text[], null, null, false, null),
('collision-system', 'Collision avoidance / driver assist off', array['amber']::text[], 'info', 'Car with crash marks or wavy radar lines in front, often with OFF.', 'Forward collision warning or automatic emergency braking is turned off or unavailable.', 'Clean the front sensors and windshield camera. Check the settings menu in case it was switched off.', 'OK to drive with extra attention.', '{"subaru": "On Subarus this appears as ''EyeSight OFF'' or ''EyeSight Disabled'', often from a dirty windshield, glare or heavy rain.", "toyota": "Toyota calls this the Pre-Collision System (PCS).", "honda": "Honda calls this the Collision Mitigation Braking System (CMBS)."}'::jsonb, '{}'::jsonb, 29, null, array[]::text[], null, null, false, null),
('cruise-control', 'Cruise control', array['green','white']::text[], 'info', 'Speedometer dial with an arrow pointing at it.', 'Cruise control is on or set.', 'Nothing to fix.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 30, null, array[]::text[], null, null, false, null),
('high-beam', 'High beams on', array['blue']::text[], 'info', 'D-shaped headlight with straight horizontal lines.', 'The high-beam headlights are on.', 'Switch to low beams for oncoming traffic.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 31, null, array[]::text[], null, null, false, null),
('headlights', 'Headlights on', array['green']::text[], 'info', 'Two small lamps facing outward with short rays, or a D-shaped lamp with angled lines.', 'The headlights or parking lights are on.', 'Nothing to fix.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 32, null, array[]::text[], null, null, false, null),
('fog-lights', 'Fog lights on', array['green','amber']::text[], 'info', 'Lamp with angled lines crossed by a wavy line.', 'Front fog lights (green) or rear fog light (amber) are on.', 'Turn rear fog lights off in clear weather. They dazzle drivers behind you.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 33, null, array[]::text[], null, null, false, null),
('auto-stop-start', 'Auto stop-start', array['green','amber']::text[], 'info', 'Letter A inside a circular arrow.', 'Green: the engine has shut off at a stop to save fuel. Amber or with OFF: the system is off or unavailable.', 'Nothing to fix. The engine restarts when you lift off the brake.', 'OK to drive.', '{"mazda": "Mazda calls this i-stop."}'::jsonb, '{}'::jsonb, 34, null, array[]::text[], null, null, false, null),
('key-not-detected', 'Key fob not detected / low key battery', array['red','amber']::text[], 'info', 'Key shape, sometimes with an exclamation mark or inside a car outline.', 'The car can''t detect the key fob, often because its battery is low.', 'Hold the fob against the start button to start, and replace the fob battery soon.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 35, null, array[]::text[], null, null, false, null),
('hybrid-system', 'Hybrid / EV system warning', array['red','amber']::text[], 'soon', 'Car outline with an exclamation mark, or a battery with a plug.', 'The hybrid or electric drive system has a fault.', 'Pull over when safe, restart the car, and if it stays on, contact a dealer. Don''t try to service high-voltage parts yourself.', 'Drive only if the car still drives normally, directly to service.', '{"toyota": "Toyota hybrids show ''Check Hybrid System''.", "tesla": "Tesla shows these alerts on the touchscreen; check the alert code there."}'::jsonb, '{}'::jsonb, 36, 'Electrical', array['Engine']::text[], 200, 3000, true, 'Often the 12-volt battery, a cooling fan or the inverter coolant ($150–$800). A hybrid battery replacement can run $2,000–$4,000 or more, so ask a hybrid specialist or dealer to quote it.'),
('ready', 'Ready to drive (hybrid / EV)', array['green']::text[], 'info', 'The word READY or a car with arrows.', 'A hybrid or electric car is on and ready to move, even though it''s silent.', 'Nothing to fix.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 37, null, array[]::text[], null, null, false, null),
('coolant-level-low', 'Low coolant level', array['amber']::text[], 'soon', 'Coolant reservoir or radiator symbol with wavy liquid lines.', 'The engine coolant level is low, possibly because of a leak.', 'Stop somewhere safe and let the engine cool completely. Check the coolant reservoir and follow the owner''s manual for the correct coolant. Never open a hot cooling system.', 'Do not continue driving if the engine is overheating, coolant is leaking heavily, or the warning is red.', '{}'::jsonb, '{}'::jsonb, 38, 'Engine', array[]::text[], 50, 600, false, 'A top-off with the right coolant may be all it needs. If it drops again, fixing the leak (hose, radiator or water pump) costs $150–$900.'),
('transmission-fault', 'Transmission fault', array['amber','red']::text[], 'soon', 'Gear symbol with an exclamation mark, or a transmission warning message.', 'The transmission or its electronic controls have detected a fault.', 'Check for unusual shifting, slipping, or warning messages. Arrange a diagnostic inspection promptly.', 'Stop driving if the transmission slips badly, loses drive, overheats, or displays a stop warning.', '{}'::jsonb, '{}'::jsonb, 39, 'Transmission', array[]::text[], 200, 2500, true, 'Often a sensor, solenoid or fluid problem ($200–$800). A rebuild or replacement can cost $2,500–$5,000 or more.'),
('reduced-engine-power', 'Reduced engine power', array['amber']::text[], 'soon', 'Engine symbol with a downward arrow or a reduced-power message.', 'The vehicle has limited engine output after detecting a problem.', 'Avoid hard acceleration and arrange a diagnostic inspection. Follow any additional dashboard instructions.', 'Only drive a short distance to safety or service if the vehicle responds normally enough to do so.', '{}'::jsonb, '{}'::jsonb, 40, 'Engine', array['Electrical']::text[], 150, 1200, true, 'Usually the throttle body, the accelerator pedal sensor or wiring ($200–$800).'),
('electronic-throttle', 'Electronic throttle control warning', array['amber','red']::text[], 'soon', 'Lightning bolt between two curved brackets, or an electronic throttle warning.', 'The electronic throttle control system has detected a fault.', 'Avoid sudden acceleration and have the vehicle inspected. If throttle response is abnormal, pull over safely.', 'Do not continue driving if acceleration becomes unpredictable or the vehicle cannot maintain safe speed.', '{}'::jsonb, '{}'::jsonb, 41, 'Engine', array['Electrical']::text[], 100, 800, true, 'Usually the throttle body: cleaning is about $100–$150, replacement $300–$700.'),
('diesel-water-filter', 'Water in fuel filter (diesel)', array['amber']::text[], 'soon', 'Fuel filter symbol with a water droplet or wavy line.', 'Water has accumulated in the diesel fuel filter or water separator.', 'Follow the vehicle manual''s water-separator draining instructions or arrange professional service.', 'Address promptly to reduce the risk of fuel-system damage.', '{}'::jsonb, '{}'::jsonb, 42, 'Engine', array[]::text[], 60, 300, false, 'Drain the water separator or replace the fuel filter ($80–$300).'),
('adaptive-cruise-unavailable', 'Adaptive cruise control unavailable', array['amber']::text[], 'info', 'Car and speedometer or radar-distance symbol with an OFF indicator.', 'Adaptive cruise control is switched off, temporarily unavailable, or malfunctioning.', 'Drive without relying on adaptive cruise control. Check for blocked sensors and review dashboard messages.', 'Normal manual driving is generally possible.', '{}'::jsonb, '{}'::jsonb, 43, null, array[]::text[], null, null, false, null),
('blind-spot-warning', 'Blind spot monitoring unavailable', array['amber']::text[], 'soon', 'Two cars beside each other, a side mirror symbol, or BSM with a warning indicator.', 'The blind spot monitoring system is unavailable or has detected a fault.', 'Check for dirt, ice, or snow covering the sensors. If the warning persists, arrange service.', 'Use mirrors and shoulder checks; do not rely on blind spot alerts.', '{}'::jsonb, '{}'::jsonb, 44, 'Electrical', array[]::text[], 100, 900, true, 'Often just a dirty or iced-over bumper sensor (free to clean). A failed radar sensor or recalibration runs $300–$1,000.'),
('hill-descent', 'Hill descent control', array['green','amber']::text[], 'info', 'Vehicle descending a steep slope, sometimes with a speedometer.', 'Hill descent control may be active, unavailable, or malfunctioning depending on the symbol and color.', 'Check the dashboard message and owner''s manual to determine the system''s status.', 'Drive carefully on steep slopes and do not rely on the feature when unavailable.', '{}'::jsonb, '{}'::jsonb, 45, null, array[]::text[], null, null, false, null),
('awd-4wd-fault', 'AWD / 4WD system warning', array['amber']::text[], 'soon', 'AWD, 4WD, or drivetrain diagram with a warning indicator.', 'The all-wheel-drive or four-wheel-drive system has detected a fault or is temporarily unavailable.', 'Check dashboard messages, avoid demanding driving conditions, and arrange an inspection if the warning persists.', 'Avoid off-road driving, towing, or slippery conditions until the problem is understood.', '{}'::jsonb, '{}'::jsonb, 46, 'Transmission', array['Electrical']::text[], 150, 1500, true, 'Often a sensor or actuator ($200–$700). Transfer case or coupling repairs cost more.'),
('ev-battery-temperature', 'EV battery temperature warning', array['red','amber']::text[], 'stop', 'High-voltage battery with a thermometer or temperature warning.', 'The high-voltage battery temperature is outside its safe operating range.', 'Follow the vehicle''s dashboard instructions. For a red warning or instruction to stop, pull over safely, switch off the vehicle, and request assistance.', 'Do not continue driving with a red battery-temperature warning or stop message.', '{}'::jsonb, '{}'::jsonb, 47, 'Electrical', array[]::text[], 200, 2000, true, 'Stop and let the battery cool. Battery cooling repairs usually need a dealer or an EV-certified shop ($200–$2,000 or more).')
